input.newString:
'use client';

import { useState } from 'react';
import { revalidatePath } from 'next/cache';

// Mock database to store user preferences
const userPreferences = new Map<string, boolean>();
userPreferences.set('user123', true); // Default to notifications on

export async function toggleNotificationPreference() {
  // Get current preference (in a real app, this would come from a database)
  const currentPreference = userPreferences.get('user123') || false;

  // Toggle the preference
  const newPreference = !currentPreference;
  userPreferences.set('user123', newPreference);

  // Refresh the current page to show updated preference
  // This is the recommended Next.js approach for refreshing the current page
  revalidatePath('/settings');

  return { success: true, preference: newPreference };
}

export default function Home() {
  const [preference, setPreference] = useState(true);

  const handleToggle = async () => {
    const result = await toggleNotificationPreference();
    if (result.success) {
      setPreference(result.preference);
    }
  };

  return (
    <main>
      <h1>Settings</h1>
      <div>
        <label>
          <input
            type="checkbox"
            checked={preference}
            onChange={handleToggle}
          />
          Enable notifications
        </label>
        <p>Current preference: {preference ? 'Enabled' : 'Disabled'}</p>
      </div>
    </main>
  );
}

